import { SEMESTERS, SCHOOL_SKILLS } from './school.mjs?v=school20261027';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function schoolHome(course,game,group='junior') {
 const semesters=SEMESTERS.filter(s=>s.group===group);
 return `<section class="page-head"><div><p class="eyebrow">108 課綱 · 六學期自學路徑</p><h1>三年，一學期一個完整任務</h1><p class="muted">國中六單元、高中六單元，串起教材、闖關與作品。這是依學習階段目標編排的本站順序，可自由選擇與回頭補強。</p></div></section><div class="school-switch" role="group" aria-label="選擇學段">${[['junior','🎒 國中六學期'],['senior','🎓 高中六學期']].map(([id,label])=>`<button class="btn ${group===id?'primary':''}" data-act="school-group" data-id="${id}" aria-pressed="${group===id}">${label}</button>`).join('')}</div><div class="semester-grid">${semesters.map((s,i)=>{
 const completed=SCHOOL_SKILLS.filter(([skill])=>skill!=='boss'&&game.state.nodes[`sem-${s.id}:${skill}`]?.n).length,crown=!!game.state.crowns[`sem-${s.id}-unit`];
 return `<article class="semester-card"><p class="eyebrow">第 ${i+1} 單元 · ${esc(s.label)}</p><h2>${esc(s.title)}</h2><p class="muted small">${s.modules.length} 個主題教材 · 4 個學習關＋1 個挑戰關</p><ul>${s.goals.slice(0,3).map(g=>`<li>${esc(g)}</li>`).join('')}</ul><p class="semester-progress">學習關 ${completed}/4 · ${crown?'👑 題目挑戰已通過':'🏆 題目挑戰待確認'}</p><button class="btn primary" data-act="track" data-id="sem-${s.id}">展開${esc(s.label)} →</button></article>`;
 }).join('')}</div><p class="school-note">普通型高中高三下以加深加廣、自主學習與專題整合安排；會考、統測與證照教材另列延伸，不作為所有學生共同必修。作品自評與題目挑戰成績分開記錄。</p>`;
}
export function schoolGuide(s,course) {
 const title=id=>course.units.get(id)?.title || id;
 return `<section class="semester-guide-content"><h2>${esc(s.label)}｜${esc(s.title)}</h2><p class="muted">先備：${esc(s.prerequisite)}</p><h3>這學期要做到</h3><ul>${s.goals.map(g=>`<li>${esc(g)}</li>`).join('')}</ul><h3>語言工具與策略</h3><p>${s.grammar.map(esc).join(' · ')}</p><p class="school-rule">${esc(s.rule)}</p><p lang="en" class="example">${esc(s.example)} <button class="say" data-act="say" data-text="${esc(s.example)}" aria-label="朗讀範例">🔊</button></p><h3>先理解教材，再到下方闖關</h3><div class="semester-resources">${s.modules.map((id,i)=>`<a href="../#unit/${id}"><b>${i+1}. ${esc(title(id))}</b><small>觀念、字詞、會話與練習 ↗</small></a>`).join('')}</div><h3>學習表現對照</h3><p class="standard-codes">${s.codes.map(c=>`<a href="../#standards" aria-label="課綱代碼 ${esc(c)}">${esc(c)}</a>`).join('')}</p><h3>學習內容對照</h3><p class="standard-codes">${s.contentCodes.map(c=>`<a href="../#standards">${esc(c)}</a>`).join('')}</p><p class="muted small">代碼對照第四／第五學習階段；各學期順序及作品字數為本站自學建議。</p>${s.extensions.length?`<details><summary>考試與目標延伸（依需求選擇）</summary>${s.extensions.map(id=>`<p><a href="../#unit/${id}">${esc(title(id))} ↗</a></p>`).join('')}</details>`:''}</section>`;
}
export function semesterIntro(s,course,game) {
 return `<section class="track-head ${s.group==='junior'?'teal':'indigo'}"><div><p class="eyebrow">108 課綱學期單元 · 自由選關</p><h1>${esc(s.label)}｜${esc(s.title)}</h1><p>先理解 → 聽與讀 → 自己表達 → 混合挑戰 → 作品修訂</p></div><a class="btn" href="#school">← 六學期總覽</a></section><details class="semester-guide card"><summary>📘 展開本學期目標、教材與課綱對照</summary>${schoolGuide(s,course)}</details>`;
}
export function semesterProject(s,game) {
 const work=game.state.schoolWork?.[s.id] || {text:'',checks:[]};
 return `<section class="semester-project card" data-semester="${s.id}"><p class="eyebrow">開口、寫作與修訂 · 自我檢核</p><h2>🎒 ${esc(s.label)}作品任務</h2><p>${esc(s.project)}</p><details><summary>先自己試，再看示範與跟讀</summary><p lang="en">${esc(s.model)}</p><button class="btn small" data-act="say" data-text="${esc(s.model)}">🔊 聽示範</button></details><label for="school-draft">我的草稿與修訂紀錄</label><textarea id="school-draft" maxlength="6000" rows="7" placeholder="先寫初稿，再記錄你依據回饋修改的地方。">${esc(work.text)}</textarea><fieldset><legend>完成後，用證據檢查自己的作品</legend>${s.rubric.map((r,i)=>`<label><input class="school-check" type="checkbox" data-i="${i}" ${work.checks[i]?'checked':''}>${esc(r)}</label>`).join('')}</fieldset><p class="muted small" id="school-save-status" role="status">${work.at?'已儲存於此瀏覽器':'輸入後自動儲存於此瀏覽器，並包含在進度備份。'}</p><p class="muted small">這是自評，網站不會自動判定口說或文章品質；不另發 XP，也不替代題目挑戰或教師回饋。</p></section>`;
}
